-- Additive directory for opt-in public non-Mafia rooms. Existing rooms stay private.
CREATE TABLE IF NOT EXISTS online_public_rooms (room_code TEXT PRIMARY KEY, room_key TEXT NOT NULL, game TEXT NOT NULL CHECK(game IN ('badeeha','ersomha','fabraka','meenfina')), room_name TEXT NOT NULL, host_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, member_user_ids TEXT NOT NULL, players INTEGER NOT NULL CHECK(players >= 0 AND players <= 12), capacity INTEGER NOT NULL CHECK(capacity >= 2 AND capacity <= 12), minimum INTEGER NOT NULL CHECK(minimum >= 2 AND minimum <= capacity), status TEXT NOT NULL CHECK(status IN ('waiting','playing')), joinable INTEGER NOT NULL CHECK(joinable IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS online_public_rooms_listing ON online_public_rooms(game,created_at DESC,room_code DESC,expires_at);
